  #define H(p)  fract(sin(dot(p, vec2(12.9898, 78.233))) * 1e4 ) // hash
//#define H(p)  texelFetch(iChannel0,ivec2(p+50.),0).r  // bluenoise texture


void mainImage(out vec4 O, vec2 u)
{
    vec2 R = iResolution.xy,
         U = 15.* u / R.y * mat2(1,-1,1,1),             // scaling + 45° rot
         I = floor(U),                                  // grid ID
         A = abs(U -= I +.5);                           // local cell coordinates

    if (int(I+I.y)%2<1) U = U.yx;                       // truchet orientation
 // if (H(I)>.5) U = U.yx;                              // random variant

    float v = H( U.x<0. ?I :I+.7 );                     // color choice for each bean of the truchet
    U.x = abs(U.x)-.5;                                  // exploit truchet symmetry )(

    O = mix( vec4(0,.2,.7,0),                           // background color
             v<.1 ? vec4(1,.4,0,0) : v<.5 ? vec4(0,1,1,0) : vec4(0,.6,1,0), // pattern color
             smoothstep( 20./R.y, 0.,                   // pattern
                 min( max( abs(length(U)-.3) -.1 ,      // bean C shape
                           max(A.x,A.y)-.4) ,           // clamped at tile border for rounding
                      length(abs(U)-vec2(.1,.28)) -.1   // rounding
            ) )      );
}
